<script setup>
definePageMeta({layout:'default'});import {useOpportunities} from '~/modules/opportunities/useOpportunities';const {opportunities}=await useOpportunities();const { value }=await useManagedPageContent('oportunidades');const ctaText=value('contact-cta','content','Queres garantir o teu kit oficial ou esclarecer alguma dúvida? Entra em contacto com a direção.');const ctaItems=value('contact-cta','items',['Contactar Direção|/contacto|primary']);const ctaAction=computed(()=>{const [label,url]=String(ctaItems.value?.[0]||'Contactar Direção|/contacto').split('|');return{label,url:url||'/contacto'}});
</script>
<template><LandingContainer><CmsManagedPageHeader page-slug="oportunidades" fallback-title="Oportunidades Exclusivas para Sócios" fallback-description="Garante já o teu kit oficial do clube com condições especiais nas cotas. Escolhe a opção que preferes." /><div class="max-w-4xl mx-auto mt-12 px-3 rounded-3xl bg-transparent"><div class="w-full sm:px-0"><div v-if="opportunities.length" class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 max-w-full mx-auto rounded-xl bg-surface"><div v-for="item in opportunities" :key="item.id" class="p-6 rounded-xl border border-neutral-200 text-center text-primary-700 transition flex flex-col justify-between hover:shadow-lg hover:scale-[1.03] hover:duration-300"><p class="text-fluid-xl font-semibold tracking-wide mb-6">{{item.title}}</p><p class="text-fluid-4xl font-extrabold tracking-tight">{{item.price}}</p></div></div><div v-else class="card-surface p-8 text-center text-neutral-600">Neste momento não existem oportunidades publicadas.</div><div class="mt-12 text-center"><p class="text-neutral-600 mb-6 text-fluid-lg">{{ctaText}}</p><NuxtLink :to="ctaAction.url" class="bg-secondary-800 text-white hover:bg-secondary-900 hover:text-white border border-secondary-800 hover:border-secondary-900 w-full sm:w-auto inline-block text-center px-6 py-3 rounded font-semibold transition">{{ctaAction.label}}</NuxtLink></div></div></div></LandingContainer></template>
